21: // Package fx is a framework that makes it easy to build applications out of
22: // reusable, composable modules.
23: //
24: // Fx applications use dependency injection to eliminate globals without the
25: // tedium of manually wiring together function calls. Unlike other approaches
26: // to dependency injection, Fx works with plain Go functions: you don't need
27: // to use struct tags or embed special types, so Fx automatically works well
28: // with most Go packages.
29: //
30: // # Basic usage
31: //
32: // Basic usage is explained in the package-level example.
33: // If you're new to Fx, start there!
34: //
35: // Advanced features, including named instances, optional parameters,
36: // and value groups, are explained in this section further down.
37: //
38: // # Testing Fx Applications
39: //
40: // To test functions that use the Lifecycle type or to write end-to-end tests
41: // of your Fx application, use the helper functions and types provided by the
42: // go.uber.org/fx/fxtest package.
43: //
44: // # Parameter Structs
45: //
46: // Fx constructors declare their dependencies as function parameters. This can
47: // quickly become unreadable if the constructor has a lot of dependencies.
48: //
49: //	func NewHandler(users *UserGateway, comments *CommentGateway, posts *PostGateway, votes *VoteGateway, authz *AuthZGateway) *Handler {
50: //		// ...
51: //	}
52: //
53: // To improve the readability of constructors like this, create a struct that
54: // lists all the dependencies as fields and change the function to accept that
55: // struct instead. The new struct is called a parameter struct.
56: //
57: // Fx has first class support for parameter structs: any struct embedding
58: // fx.In gets treated as a parameter struct, so the individual fields in the
59: // struct are supplied via dependency injection. Using a parameter struct, we
60: // can make the constructor above much more readable:
61: //
62: //	type HandlerParams struct {
63: //		fx.In
64: //
65: //		Users    *UserGateway
66: //		Comments *CommentGateway
67: //		Posts    *PostGateway
68: //		Votes    *VoteGateway
69: //		AuthZ    *AuthZGateway
70: //	}
71: //
72: //	func NewHandler(p HandlerParams) *Handler {
73: //		// ...
74: //	}
75: //
76: // Though it's rarely necessary to mix the two, constructors can receive any
77: // combination of parameter structs and parameters.
78: //
79: //	func NewHandler(p HandlerParams, l *log.Logger) *Handler {
80: //		// ...
81: //	}
82: //
83: // # Result Structs
84: //
85: // Result structs are the inverse of parameter structs.
86: // These structs represent multiple outputs from a
87: // single function as fields. Fx treats all structs embedding fx.Out as result
88: // structs, so other constructors can rely on the result struct's fields
89: // directly.
90: //
91: // Without result structs, we sometimes have function definitions like this:
92: //
93: //	func SetupGateways(conn *sql.DB) (*UserGateway, *CommentGateway, *PostGateway, error) {
94: //		// ...
95: //	}
96: //
97: // With result structs, we can make this both more readable and easier to
98: // modify in the future:
99: //
100: //	type Gateways struct {
101: //		fx.Out
102: //
103: //		Users    *UserGateway
104: //		Comments *CommentGateway
105: //		Posts    *PostGateway
106: //	}
107: //
108: //	func SetupGateways(conn *sql.DB) (Gateways, error) {
109: //		// ...
110: //	}
111: //
112: // # Named Values
113: //
114: // Some use cases require the application container to hold multiple values of
115: // the same type.
116: //
117: // A constructor that produces a result struct can tag any field with
118: // `name:".."` to have the corresponding value added to the graph under the
119: // specified name. An application may contain at most one unnamed value of a
120: // given type, but may contain any number of named values of the same type.
121: //
122: //	type ConnectionResult struct {
123: //		fx.Out
124: //
125: //		ReadWrite *sql.DB `name:"rw"`
126: //		ReadOnly  *sql.DB `name:"ro"`
127: //	}
128: //
129: //	func ConnectToDatabase(...) (ConnectionResult, error) {
130: //		// ...
131: //		return ConnectionResult{ReadWrite: rw, ReadOnly:  ro}, nil
132: //	}
133: //
134: // Similarly, a constructor that accepts a parameter struct can tag any field
135: // with `name:".."` to have the corresponding value injected by name.
136: //
137: //	type GatewayParams struct {
138: //		fx.In
139: //
140: //		WriteToConn  *sql.DB `name:"rw"`
141: //		ReadFromConn *sql.DB `name:"ro"`
142: //	}
143: //
144: //	func NewCommentGateway(p GatewayParams) (*CommentGateway, error) {
145: //		// ...
146: //	}
147: //
148: // Note that both the name AND type of the fields on the
149: // parameter struct must match the corresponding result struct.
150: //
151: // # Optional Dependencies
152: //
153: // Constructors often have optional dependencies on some types: if those types are
154: // missing, they can operate in a degraded state. Fx supports optional
155: // dependencies via the `optional:"true"` tag to fields on parameter structs.
156: //
157: //	type UserGatewayParams struct {
158: //		fx.In
159: //
160: //		Conn  *sql.DB
161: //		Cache *redis.Client `optional:"true"`
162: //	}
163: //
164: // If an optional field isn't available in the container, the constructor
165: // receives the field's zero value.
166: //
167: //	func NewUserGateway(p UserGatewayParams, log *log.Logger) (*UserGateway, error) {
168: //		if p.Cache == nil {
169: //			log.Print("Caching disabled")
170: //		}
171: //		// ...
172: //	}
173: //
174: // Constructors that declare optional dependencies MUST gracefully handle
175: // situations in which those dependencies are absent.
176: //
177: // The optional tag also allows adding new dependencies without breaking
178: // existing consumers of the constructor.
179: //
180: // The optional tag may be combined with the name tag to declare a named
181: // value dependency optional.
182: //
183: //	type GatewayParams struct {
184: //		fx.In
185: //
186: //		WriteToConn  *sql.DB `name:"rw"`
187: //		ReadFromConn *sql.DB `name:"ro" optional:"true"`
188: //	}
189: //
190: //	func NewCommentGateway(p GatewayParams, log *log.Logger) (*CommentGateway, error) {
191: //		if p.ReadFromConn == nil {
192: //			log.Print("Warning: Using RW connection for reads")
193: //			p.ReadFromConn = p.WriteToConn
194: //		}
195: //		// ...
196: //	}
197: //
198: // # Value Groups
199: //
200: // To make it easier to produce and consume many values of the same type, Fx
201: // supports named, unordered collections called value groups.
202: //
203: // Constructors can send values into value groups by returning a result struct
204: // tagged with `group:".."`.
205: //
206: //	type HandlerResult struct {
207: //		fx.Out
208: //
209: //		Handler Handler `group:"server"`
210: //	}
211: //
212: //	func NewHelloHandler() HandlerResult {
213: //		// ...
214: //	}
215: //
216: //	func NewEchoHandler() HandlerResult {
217: //		// ...
218: //	}
219: //
220: // Any number of constructors may provide values to this named collection, but
221: // the ordering of the final collection is unspecified.
222: //
223: // Value groups require parameter and result structs to use fields with
224: // different types: if a group of constructors each returns type T, parameter
225: // structs consuming the group must use a field of type []T.
226: //
227: // Parameter structs can request a value group by using a field of type []T
228: // tagged with `group:".."`.
229: // This will execute all constructors that provide a value to
230: // that group in an unspecified order, then collect all the results into a
231: // single slice.
232: //
233: //	type ServerParams struct {
234: //		fx.In
235: //
236: //		Handlers []Handler `group:"server"`
237: //	}
238: //
239: //	func NewServer(p ServerParams) *Server {
240: //		server := newServer()
241: //		for _, h := range p.Handlers {
242: //			server.Register(h)
243: //		}
244: //		return server
245: //	}
246: //
247: // Note that values in a value group are unordered. Fx makes no guarantees
248: // about the order in which these values will be produced.
249: //
250: // # Soft Value Groups
251: //
252: // By default, when a constructor declares a dependency on a value group,
253: // all values provided to that value group are eagerly instantiated.
254: // That is undesirable for cases where an optional component wants to
255: // contribute to a value group, but only if it was actually used
256: // by the rest of the application.
257: //
258: // A soft value group can be thought of as a best-attempt at populating the
259: // group with values from constructors that have already run. In other words,
260: // if a constructor's output type is only consumed by a soft value group,
261: // it will not be run.
262: //
263: // Note that Fx randomizes the order of values in the value group,
264: // so the slice of values may not match the order in which constructors
265: // were run.
266: //
267: // To declare a soft relationship between a group and its constructors, use
268: // the `soft` option on the input group tag (`group:"[groupname],soft"`).
269: // This option is only valid for input parameters.
270: //
271: //	type Params struct {
272: //		fx.In
273: //
274: //		Handlers []Handler `group:"server,soft"`
275: //		Logger   *zap.Logger
276: //	}
277: //
278: //	func NewServer(p Params) *Server {
279: //		// ...
280: //	}
281: //
282: // With such a declaration, a constructor that provides a value to the 'server'
283: // value group will be called only if there's another instantiated component
284: // that consumes the results of that constructor.
285: //
286: //	func NewHandlerAndLogger() (Handler, *zap.Logger) {
287: //		// ...
288: //	}
289: //
290: //	func NewHandler() Handler {
291: //		// ...
292: //	}
293: //
294: //	fx.Provide(
295: //		fx.Annotate(NewHandlerAndLogger, fx.ResultTags(`group:"server"`)),
296: //		fx.Annotate(NewHandler, fx.ResultTags(`group:"server"`)),
297: //	)
298: //
299: // NewHandlerAndLogger will be called because the Logger is consumed by the
300: // application, but NewHandler will not be called because it's only consumed
301: // by the soft value group.
302: //
303: // # Value group flattening
304: //
305: // By default, values of type T produced to a value group are consumed as []T.
306: //
307: //	type HandlerResult struct {
308: //		fx.Out
309: //
310: //		Handler Handler `group:"server"`
311: //	}
312: //
313: //	type ServerParams struct {
314: //		fx.In
315: //
316: //		Handlers []Handler `group:"server"`
317: //	}
318: //
319: // This means that if the producer produces []T,
320: // the consumer must consume [][]T.
321: //
322: // There are cases where it's desirable
323: // for the producer (the fx.Out) to produce multiple values ([]T),
324: // and for the consumer (the fx.In) consume them as a single slice ([]T).
325: // Fx offers flattened value groups for this purpose.
326: //
327: // To provide multiple values for a group from a result struct, produce a
328: // slice and use the `,flatten` option on the group tag. This indicates that
329: // each element in the slice should be injected into the group individually.
330: //
331: //	type HandlerResult struct {
332: //		fx.Out
333: //
334: //		Handler []Handler `group:"server,flatten"`
335: //		// Consumed as []Handler in ServerParams.
336: //	}
337: //
338: // # Unexported fields
339: //
340: // By default, a type that embeds fx.In may not have any unexported fields. The
341: // following will return an error if used with Fx.
342: //
343: //	type Params struct {
344: //		fx.In
345: //
346: //		Logger *zap.Logger
347: //		mu     sync.Mutex
348: //	}
349: //
350: // If you have need of unexported fields on such a type, you may opt-into
351: // ignoring unexported fields by adding the ignore-unexported struct tag to the
352: // fx.In. For example,
353: //
354: //	type Params struct {
355: //		fx.In `ignore-unexported:"true"`
356: //
357: //		Logger *zap.Logger
358: //		mu     sync.Mutex
359: //	}
