            "manifests_as": {"type": "array", "items": {"type": "string"}, "description": "若该阻碍体现为具体不可适配 API，引用 unadaptable_apis[].id（可空）。"},
            "evidence": {"type": "array", "items": {"type": "string"}, "description": "复用来源维度的 file:line"}}},
