24: 	"context"
25: 	"fmt"
26: 	"os"
27: 	"os/signal"
28: 	"sync"
29: )
30: 
31: // ShutdownSignal represents a signal to be written to Wait or Done.
32: // Should a user call the Shutdown method via the Shutdowner interface with
33: // a provided ExitCode, that exit code will be populated in the ExitCode field.
34: //
35: // Should the application receive an operating system signal,
36: // the Signal field will be populated with the received os.Signal.
37: type ShutdownSignal struct {
38: 	Signal   os.Signal
39: 	ExitCode int
40: }
41: 
42: // String will render a ShutdownSignal type as a string suitable for printing.
43: func (sig ShutdownSignal) String() string {
44: 	return fmt.Sprintf("%v", sig.Signal)
45: }
46: 
47: func newSignalReceivers() signalReceivers {
48: 	return signalReceivers{
49: 		notify:     signal.Notify,
50: 		stopNotify: signal.Stop,
51: 		signals:    make(chan os.Signal, 1),
52: 		b:          &broadcaster{},
53: 	}
54: }
55: 
56: // signalReceivers listens to OS signals and shutdown signals,
57: // and relays them to registered listeners when started.
58: type signalReceivers struct {
59: 	// this mutex protects writes and reads of this struct to prevent
60: 	// race conditions in a parallel execution pattern
61: 	m sync.Mutex
62: 
63: 	// our os.Signal channel we relay from
64: 	signals chan os.Signal
65: 	// when written to, will instruct the signal relayer to shutdown
66: 	shutdown chan struct{}
67: 	// is written to when signal relay has finished shutting down
68: 	finished chan struct{}
69: 
70: 	// this stub allows us to unit test signal relay functionality
71: 	notify     func(c chan<- os.Signal, sig ...os.Signal)
72: 	stopNotify func(c chan<- os.Signal)
73: 
74: 	// used to register and broadcast to signal listeners
75: 	// created via Done and Wait
76: 	b *broadcaster
77: }
78: 
79: func (recv *signalReceivers) relayer() {
80: 	defer func() {
81: 		recv.finished <- struct{}{}
82: 	}()
83: 
84: 	select {
85: 	case <-recv.shutdown:
86: 		return
87: 	case signal := <-recv.signals:
88: 		recv.b.Broadcast(ShutdownSignal{
89: 			Signal: signal,
90: 		})
91: 	}
92: }
93: 
94: // running returns true if the the signal relay go-routine is running.
95: // this method must be invoked under locked mutex to avoid race condition.
96: func (recv *signalReceivers) running() bool {
97: 	return recv.shutdown != nil && recv.finished != nil
98: }
99: 
100: func (recv *signalReceivers) Start() {
101: 	recv.m.Lock()
102: 	defer recv.m.Unlock()
103: 
104: 	// if the receiver has already been started; don't start it again
105: 	if recv.running() {
106: 		return
107: 	}
108: 
109: 	recv.finished = make(chan struct{}, 1)
110: 	recv.shutdown = make(chan struct{}, 1)
111: 	recv.notify(recv.signals, os.Interrupt, _sigINT, _sigTERM)
112: 	go recv.relayer()
113: }
114: 
115: func (recv *signalReceivers) Stop(ctx context.Context) error {
116: 	recv.m.Lock()
117: 	defer recv.m.Unlock()
118: 	recv.stopNotify(recv.signals)
119: 
120: 	// if the relayer is not running; return nil error
121: 	if !recv.running() {
122: 		return nil
123: 	}
124: 
125: 	recv.shutdown <- struct{}{}
126: 
127: 	select {
128: 	case <-ctx.Done():
129: 		return ctx.Err()
130: 	case <-recv.finished:
131: 		close(recv.shutdown)
132: 		close(recv.finished)
133: 		recv.shutdown = nil
134: 		recv.finished = nil
135: 		recv.b.reset()
136: 		return nil
137: 	}
138: }
139: 
140: func (recv *signalReceivers) Done() <-chan os.Signal {
141: 	return recv.b.Done()
142: }
143: 
